pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, address actor) public {
        // Bound amounts to reasonable ranges to avoid overflow in test arithmetic
        depositAmount = bound(depositAmount, 0, type(uint128).max);
        collectAmount = bound(collectAmount, 0, type(uint128).max);
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));

        // Initialize the contract
        c.Initialized();

        // Deposit: deal ether to actor and prank
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        // Record total deposited (only from this test, since contract starts with 0)
        uint256 totalDeposited = depositAmount;

        // Collect: ensure actor can collect
        if (collectAmount > 0) {
            vm.prank(actor);
            try c.Collect(collectAmount) {} catch {}
        }

        // Calculate sum of all balances in mapping (we cannot iterate, so we compute from known deposits)
        // In the reference, only actor has nonzero balance; in buggy, address(0) has the deposit.
        // We compare contract ether balance + actor balance + address(0) balance to totalDeposited.
        uint256 balanceActor = c.balances(actor);
        uint256 balanceZero = c.balances(address(0));
        uint256 contractBalance = address(c).balance;

        // The invariant: totalDeposited = contractBalance + balanceActor + balanceZero
        // In reference: balanceZero = 0, contractBalance = totalDeposited - balanceActor (since collect subtracts from actor balance and sends ether)
        // In buggy: balanceZero receives deposits, contractBalance = totalDeposited - balanceZero, but actor never gets balance, so collect may fail/reduce actor from 0.
        assertEq(totalDeposited, contractBalance + balanceActor + balanceZero);
    }
}

