pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint96 collectAmt) public {
        // Restrict to a realistic domain: valid caller, non-zero collect amount, and MinSum constraint
        vm.assume(caller != address(0));
        vm.assume(collectAmt > 0);
        vm.assume(collectAmt <= type(uint96).max);

        // Setup: fund caller and deposit into the contract via the reference Deposit entry point.
        // The deposit credits msg.sender (the caller), establishing some balance for the fuzzed caller.
        uint256 depositAmt = uint256(collectAmt) + 1 ether; // ensure balance >= MinSum (1 ether) and >= collectAmt
        vm.deal(caller, depositAmt);
        vm.prank(caller);
        c.Deposit{value: depositAmt}();

        // Record the caller's balance before Collect
        uint256 balBefore = c.balances(caller);

        // Attempt Collect as the caller
        vm.prank(caller);
        try c.Collect(uint256(collectAmt)) {
            // Success: after Collect the caller's balance must have decreased by at least collectAmt
            uint256 balAfter = c.balances(caller);
            assertTrue(balBefore - balAfter >= uint256(collectAmt));
        } catch {
            // If Collect reverts, the invariant vacuously holds - nothing to assert.
            // We could also assert that balance is unchanged, but the required single assertion is for the success path.
        }
    }
}

